package com.opencrm.order.finance;
import com.opencrm.common.order.AcceptedOrderSnapshot;
import com.opencrm.common.order.AcceptedOrderSnapshot.Line;
import com.opencrm.order.dto.OrderDtos.*;
import com.opencrm.order.domain.OrderProblem;
import com.opencrm.order.security.OrderAccess;
import com.opencrm.order.service.OrderService;
import com.opencrm.order.execution.ExecutionService;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.flywaydb.core.Flyway;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.*;
import tools.jackson.databind.json.JsonMapper;
import java.time.*;
import java.util.*;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;
@Tag("integration") @Testcontainers
class FinanceIntegrationTest {
 @Container static PostgreSQLContainer<?> postgres=new PostgreSQLContainer<>("postgres:16-alpine").withDatabaseName("oms");
 JdbcTemplate db;OrderAccess access;OrderService orders;ExecutionService execution;FinanceService finance;JsonMapper json=JsonMapper.builder().build();
 @BeforeAll static void migrate(){Flyway.configure().dataSource(postgres.getJdbcUrl(),postgres.getUsername(),postgres.getPassword()).schemas("order_management").defaultSchema("order_management").load().migrate();}
 @BeforeEach void setup(){var ds=new DriverManagerDataSource(postgres.getJdbcUrl()+"&currentSchema=order_management",postgres.getUsername(),postgres.getPassword());db=new JdbcTemplate(ds);db.execute("TRUNCATE snapshot_inbox,outbox_events,execution_inbox CASCADE");var manager=new DataSourceTransactionManager(ds);access=mock(OrderAccess.class);when(access.actor()).thenReturn("finance-operator");when(access.scopeId()).thenReturn("pilot");when(access.customerIds()).thenReturn(Set.of("customer"));orders=new OrderService(db,manager,json,access,true,"pilot");execution=new ExecutionService(db,manager,json,access,true,"pilot");finance=new FinanceService(db,manager,json,access,orders,execution);}
 View submitted(){var line=new Line("line","product","Widget","PHYSICAL","ONE_TIME",3,"EA","10.00","0.01","0.02","30.01","ONE_TIME",null,null);var s=new AcceptedOrderSnapshot(1,"snapshot","00000000-0000-0000-0000-000000000001","Q-1",1,"pilot","customer",Instant.now(),"USD","30.00","0.01","0.02","30.01","address","approval","tax-ref","config",List.of(line));String payload=json.writeValueAsString(s);orders.acceptTrustedSnapshot(payload,OrderService.hash(payload));var o=orders.fromQuote(new FromQuote("snapshot",s.quoteId(),1),"convert");return orders.submit(o.id(),new Command(0,"go","submit"));}
 void fulfill(View o){String line=o.lines().getFirst().id();db.update("UPDATE order_lines SET allocated=3 WHERE id=?",line);execution.completeManualTask(o.id(),line,"ALLOCATION","allocation",Instant.now());db.update("UPDATE order_lines SET allocated=0,shipped=3,fulfilled=3 WHERE id=?",line);execution.completeManualTask(o.id(),line,"SHIPMENT","shipment",Instant.now());db.update("UPDATE order_lines SET delivered=3 WHERE id=?",line);execution.completeManualTask(o.id(),line,"DELIVERY","delivery",Instant.now());}
 Command command(View o,String key){return new Command(orders.get(o.id()).version(),"verified external finance",key);}
 FinanceDtos.Acknowledgment ack(View o,String key,String ref,int qty,String outcome){return new FinanceDtos.Acknowledgment(orders.get(o.id()).version(),"verified external finance",key,o.lines().getFirst().id(),qty,ref,Instant.parse("2026-09-01T00:00:00Z"),null,outcome);}
 @Test void requestIsPendingAndPartialActualAcknowledgmentsAllocateEveryCent(){var o=submitted();fulfill(o);String line=o.lines().getFirst().id();var c=command(o,"prepare");finance.prepare(o.id(),line,c);finance.prepare(o.id(),line,c);assertEquals(1,db.queryForObject("SELECT count(*) FROM outbox_events WHERE event_type='oms.finance-requested.v1'",Integer.class));assertEquals("REQUESTED",orders.get(o.id()).financeStatus());assertNotEquals("COMPLETED",orders.get(o.id()).status());for(int i=1;i<=3;i++){finance.acknowledge(o.id(),ack(o,"ack"+i,"invoice"+i,1,"ACKNOWLEDGED"));assertEquals(i<3?"PARTIAL":"ACKNOWLEDGED",orders.get(o.id()).financeStatus());}assertEquals("COMPLETED",orders.get(o.id()).status());assertEquals(1L,db.queryForObject("SELECT sum(discount_cents) FROM finance_acknowledgments",Long.class));assertEquals(2L,db.queryForObject("SELECT sum(tax_cents) FROM finance_acknowledgments",Long.class));assertEquals(3001L,db.queryForObject("SELECT sum(total_cents) FROM finance_acknowledgments",Long.class));}
 @Test void unknownAndRejectedCannotCompleteOrRedispatch(){var o=submitted();fulfill(o);finance.prepare(o.id(),o.lines().getFirst().id(),command(o,"prepare"));finance.acknowledge(o.id(),ack(o,"unknown","provider-lookup",3,"UNKNOWN"));assertEquals("UNKNOWN",orders.get(o.id()).financeStatus());assertEquals(409,assertThrows(OrderProblem.class,()->finance.prepare(o.id(),o.lines().getFirst().id(),command(o,"prepare-again"))).status());assertNotEquals("COMPLETED",orders.get(o.id()).status());finance.acknowledge(o.id(),ack(o,"reject","provider-rejection",3,"REJECTED"));assertNotEquals("COMPLETED",orders.get(o.id()).status());assertTrue(db.queryForObject("SELECT count(*) FROM order_exceptions WHERE status='OPEN'",Integer.class)>0);finance.acknowledge(o.id(),ack(o,"part-confirmed","invoice-part",1,"ACKNOWLEDGED"));assertEquals("UNKNOWN",orders.get(o.id()).financeStatus());finance.acknowledge(o.id(),ack(o,"confirmed","invoice-real",2,"ACKNOWLEDGED"));assertEquals("COMPLETED",orders.get(o.id()).status());}
 @Test void replayCapsConflictsAndPermissionsHold(){var o=submitted();String line=o.lines().getFirst().id();assertEquals(409,assertThrows(OrderProblem.class,()->finance.prepare(o.id(),line,command(o,"too-early"))).status());fulfill(o);finance.prepare(o.id(),line,command(o,"prepare"));var a=ack(o,"ack","invoice",1,"ACKNOWLEDGED");finance.acknowledge(o.id(),a);finance.acknowledge(o.id(),a);finance.acknowledge(o.id(),ack(o,"duplicate-evidence","invoice",1,"ACKNOWLEDGED"));assertEquals(1,db.queryForObject("SELECT count(*) FROM finance_acknowledgments",Integer.class));assertEquals(409,assertThrows(OrderProblem.class,()->finance.acknowledge(o.id(),ack(o,"conflict","invoice",2,"ACKNOWLEDGED"))).status());assertEquals(409,assertThrows(OrderProblem.class,()->finance.acknowledge(o.id(),ack(o,"excess","invoice2",3,"ACKNOWLEDGED"))).status());doThrow(new OrderProblem(403,"Denied")).when(access).require(eq("oms:finance"),anyString(),anyString());assertEquals(403,assertThrows(OrderProblem.class,()->finance.acknowledge(o.id(),ack(o,"unauthorized","invoice3",1,"ACKNOWLEDGED"))).status());}
 @Test void ledgerOutboxAndExecutorRollBackWhenAuditFails(){var o=submitted();fulfill(o);String line=o.lines().getFirst().id();db.execute("ALTER TABLE order_audit ADD CONSTRAINT reject_finance_test CHECK(action<>'FINANCE_PREPARE')");try{assertThrows(OrderProblem.class,()->finance.prepare(o.id(),line,command(o,"prepare")));}finally{db.execute("ALTER TABLE order_audit DROP CONSTRAINT reject_finance_test");}assertEquals(0,db.queryForObject("SELECT count(*) FROM finance_requests",Integer.class));assertEquals(0,db.queryForObject("SELECT count(*) FROM outbox_events WHERE event_type='oms.finance-requested.v1'",Integer.class));finance.prepare(o.id(),line,command(o,"prepare"));db.execute("ALTER TABLE order_audit ADD CONSTRAINT reject_finance_test CHECK(action<>'FINANCE_EVIDENCE')");try{assertThrows(OrderProblem.class,()->finance.acknowledge(o.id(),ack(o,"ack","invoice",3,"ACKNOWLEDGED")));}finally{db.execute("ALTER TABLE order_audit DROP CONSTRAINT reject_finance_test");}assertEquals(0,db.queryForObject("SELECT count(*) FROM finance_acknowledgments",Integer.class));assertNotEquals("COMPLETED",orders.get(o.id()).status());assertEquals("READY",db.queryForObject("SELECT status FROM order_tasks WHERE line_id=? AND kind='FINANCE_ACK'",String.class,line));}
 @Test void immutableRecordsAndCompetingAcknowledgmentsPreserveCap() throws Exception {var o=submitted();fulfill(o);finance.prepare(o.id(),o.lines().getFirst().id(),command(o,"prepare"));var a=ack(o,"same-operation","invoice",3,"ACKNOWLEDGED");try(var pool=java.util.concurrent.Executors.newFixedThreadPool(4)){var calls=new ArrayList<java.util.concurrent.Callable<View>>();for(int i=0;i<20;i++)calls.add(()->finance.acknowledge(o.id(),a));for(var f:pool.invokeAll(calls))assertEquals("COMPLETED",f.get().status());}assertEquals(1,db.queryForObject("SELECT count(*) FROM finance_acknowledgments",Integer.class));assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE finance_requests SET payload='{}'"));assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("DELETE FROM finance_acknowledgments"));}
 @Test void fullyCancelledObligationCannotCreateRequest(){var o=submitted();db.update("UPDATE order_lines SET cancelled=ordered WHERE order_id=?",o.id());assertEquals(409,assertThrows(OrderProblem.class,()->finance.prepare(o.id(),o.lines().getFirst().id(),command(o,"prepare"))).status());assertEquals(0,db.queryForObject("SELECT count(*) FROM finance_requests",Integer.class));}
 @Test void missingRequestAndInvalidEvidenceNeverCount(){var o=submitted();fulfill(o);assertEquals(404,assertThrows(OrderProblem.class,()->finance.acknowledge(o.id(),ack(o,"unrequested","invoice",3,"ACKNOWLEDGED"))).status());finance.prepare(o.id(),o.lines().getFirst().id(),command(o,"prepare"));assertEquals(422,assertThrows(OrderProblem.class,()->finance.acknowledge(o.id(),ack(o,"invalid","",1,"ACKNOWLEDGED"))).status());assertEquals(422,assertThrows(OrderProblem.class,()->finance.acknowledge(o.id(),ack(o,"invalid","invoice",0,"ACKNOWLEDGED"))).status());assertEquals(422,assertThrows(OrderProblem.class,()->finance.acknowledge(o.id(),ack(o,"invalid","invoice",1,null))).status());}
 @Test void multipleLinesKeepIndependentSourceEconomicsAndRecurringTerms(){
  var first=new Line("digital","p1","License","DIGITAL","ONE_TIME",3,"EA","10.00","0.01","0.02","30.01","ONE_TIME",null,null);
  var second=new Line("service","p2","Support","SERVICE","RECURRING",2,"EA","7.50","0.02","0.01","14.99","MONTHLY",LocalDate.of(2026,1,1),LocalDate.of(2027,1,1));
  var s=new AcceptedOrderSnapshot(1,"multi-snapshot","00000000-0000-0000-0000-000000000002","Q-2",1,"pilot","customer",Instant.now(),"USD","45.00","0.03","0.03","45.00","address","approval","tax-ref","config",List.of(first,second));String body=json.writeValueAsString(s);orders.acceptTrustedSnapshot(body,OrderService.hash(body));var o=orders.fromQuote(new FromQuote(s.snapshotId(),s.quoteId(),1),"convert2");orders.submit(o.id(),new Command(0,"go","submit2"));
  for(var source:List.of(first,second)){String line=db.queryForObject("SELECT id FROM order_lines WHERE order_id=? AND source_line_id=?",String.class,o.id(),source.sourceLineId());db.update("UPDATE order_lines SET fulfilled=ordered WHERE id=?",line);execution.completeManualTask(o.id(),line,source==first?"PROVISION":"SERVICE","milestone-"+line,Instant.now());
   if(source==second){String task=db.queryForObject("SELECT id FROM order_tasks WHERE line_id=? AND kind='ACTIVATION'",String.class,line);var lease=execution.claim(task,"worker",Duration.ofSeconds(30)).orElseThrow();execution.dispatch(lease);var activation=new com.opencrm.common.order.ActivationAcknowledgment("activation",lease.operationKey(),o.id(),"pilot","subscription","ACKNOWLEDGED","contract-ref",Instant.now());execution.acceptActivationAck(activation,OrderService.hash(json.writeValueAsString(activation)));}
   finance.prepare(o.id(),line,command(o,"prepare-"+line));
   finance.acknowledge(o.id(),new FinanceDtos.Acknowledgment(orders.get(o.id()).version(),"actual finance","ack-"+line,line,source.quantity(),"invoice-"+line,Instant.now(),null,"ACKNOWLEDGED"));
   if(source==first)assertEquals("PARTIAL",orders.get(o.id()).financeStatus());
  }
  var requests=finance.list(o.id());assertEquals(2,requests.size());assertNotEquals(requests.get(0).requestKey(),requests.get(1).requestKey());assertEquals("COMPLETED",orders.get(o.id()).status());
  var amounts=db.queryForList("SELECT total_cents FROM finance_requests ORDER BY total_cents",Long.class);assertEquals(List.of(1499L,3001L),amounts);
  String recurring=db.queryForObject("SELECT payload FROM finance_requests WHERE total_cents=1499",String.class);var frozen=json.readTree(recurring);assertEquals("MONTHLY",frozen.path("sourceLine").path("billingFrequency").asText());assertEquals("2026-01-01",frozen.path("sourceLine").path("startDate").asText());assertEquals("tax-ref",frozen.path("taxEvidence").asText());assertEquals(2,frozen.path("milestones").size());
 }
 @Test void cancelledUnitsAreExcludedFromFrozenMoney(){var o=submitted();String line=o.lines().getFirst().id();db.update("UPDATE order_lines SET cancelled=1,allocated=2 WHERE id=?",line);execution.completeManualTask(o.id(),line,"ALLOCATION","allocation",Instant.now());db.update("UPDATE order_lines SET allocated=0,shipped=2,fulfilled=2 WHERE id=?",line);execution.completeManualTask(o.id(),line,"SHIPMENT","shipment",Instant.now());db.update("UPDATE order_lines SET delivered=2 WHERE id=?",line);execution.completeManualTask(o.id(),line,"DELIVERY","delivery",Instant.now());finance.prepare(o.id(),line,command(o,"prepare"));var request=db.queryForMap("SELECT * FROM finance_requests");assertEquals(2,request.get("quantity"));assertEquals(2000L,request.get("gross_cents"));assertEquals(0L,request.get("discount_cents"));assertEquals(1L,request.get("tax_cents"));assertEquals(2001L,request.get("total_cents"));finance.acknowledge(o.id(),ack(o,"ack","invoice",2,"ACKNOWLEDGED"));assertEquals("PARTIALLY_COMPLETED",orders.get(o.id()).status());}
}